
(function(){function read(k,f){try{var x=localStorage.getItem(k);return x?JSON.parse(x):f}catch(e){return f}}function write(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}}function text(el){return (el&&el.textContent||'').replace(/\s+/g,' ').trim()}function val(id){var e=document.getElementById(id);return e?String(e.value||'').trim():''}function checked(id){var e=document.getElementById(id);return !!(e&&e.checked)}function toast(id,msg){var t=document.getElementById(id);if(!t)return;t.textContent=msg;t.classList.add('is-show');setTimeout(function(){t.classList.remove('is-show')},1500)}function bootStudio(){var root=document.getElementById('mmdStudioR5');if(!root)return;var uploadSeed=read('mmdStudioUploadSeed',null);if(uploadSeed&&!sessionStorage.getItem('mmdStudioUploadSeedApplied')){var set=function(id,v){var e=document.getElementById(id);if(e&&v&&!e.value){e.value=v}};set('mmdStudioR5ModelName',uploadSeed.model_name);set('mmdStudioR5ModelQuery',uploadSeed.model_name);set('mmdStudioR5Direction',uploadSeed.direction);set('mmdStudioR5RunNumber',uploadSeed.run_number);var f=document.getElementById('mmdStudioR5Field');if(f&&uploadSeed.field)f.value=uploadSeed.field;var l=document.getElementById('mmdStudioR5Layer');if(l&&uploadSeed.layer)l.value=uploadSeed.layer;var cat=document.getElementById('mmdStudioR5CategoryHint');if(cat&&uploadSeed.category_path)cat.value=uploadSeed.category_path;var owner=document.getElementById('mmdStudioR5SourceOwner');if(owner&&uploadSeed.source_owner)owner.value=uploadSeed.source_owner;sessionStorage.setItem('mmdStudioUploadSeedApplied','1');setTimeout(function(){var b=document.getElementById('mmdStudioR5BuildBtn');if(b)b.click()},80)}var btn=document.getElementById('mmdStudioR5SendReviewBtn');if(btn){btn.onclick=function(e){if(e)e.preventDefault();var build=document.getElementById('mmdStudioR5BuildBtn');if(build)build.click();setTimeout(function(){var sel=root.querySelector('.mmd-studio-r5__template-card.is-selected');var out=val('mmdStudioR5OutputMode')||(document.getElementById('mmdStudioR5ModeGen')&&document.getElementById('mmdStudioR5ModeGen').classList.contains('is-active')?'Gen Image':'Use Real Photo');var seed={model_name:val('mmdStudioR5ModelName')||val('mmdStudioR5ModelQuery'),mode:out.indexOf('Gen')>-1?'gen':'real',output_mode:out,template_id:sel?sel.getAttribute('data-id'):'',template_title:sel?text(sel.querySelector('h3')):'MMD Compcard',field:val('mmdStudioR5Field'),run_number:val('mmdStudioR5RunNumber'),layer:val('mmdStudioR5Layer'),direction:val('mmdStudioR5Direction'),prompt:val('mmdStudioR5Prompt'),source:read('mmdStudioUploadSeed',null),source_checks:{layer:checked('mmdStudioR5CheckLayer'),face:checked('mmdStudioR5CheckFace'),real:checked('mmdStudioR5CheckReal'),value:checked('mmdStudioR5CheckValue')},saved_at:new Date().toISOString()};write('mmdStudioReviewSeed',seed);toast('mmdStudioR5Toast','ส่งให้ตรวจแล้ว');location.href='/internal/admin/studio/review'},60)}}}function boot(){var p=location.pathname.replace(/\/+$/,'')||'/';if(p==='/studio')bootStudio()}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();})();
